UPDATE … jsonb_set(default_config,'{workflow,steps,process_sections_loop,config,sub_workflow,steps,rewrite_negations}', '<step>')
 WHERE type='page-content-writer' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL
   AND default_config #>> '{workflow,steps,process_sections_loop,config,sub_workflow,steps,generate_content,action}' = 'execute_llm_prompt'
   AND default_config #>> '{workflow,steps,process_sections_loop,config,sub_workflow,steps,render_section,action}' = 'render_component'
   AND (…,rewrite_negations) IS NULL;   -- needle gate: a re-run is a 0-row no-op
UPDATE … set generate_content.next_step = 'rewrite_negations'  WHERE its current next_step = 'render_section'
   AND …,rewrite_negations,action = 'rewrite_negations';       -- the new step exists first
DO $$ … count POSITIVE presence of BOTH ends of the chain (incl. rewrite_negations.next_step='render_section');
        IF n <> 1 THEN RAISE EXCEPTION … END $$;
